package dev.cosmerearcanists.power;
import java.util.*;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.CosmereArcanists;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Pig;
import net.minecraft.world.entity.item.PrimedTnt;
import net.minecraft.world.entity.projectile.Snowball;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class BubbleGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"BubbleTest"));p.setGameMode(GameType.SURVIVAL);p.getAbilities().invulnerable=false;p.setPos(Vec3.atCenterOf(h.absolutePos(new BlockPos(1,20,1))));return p;}
    private static FakePlayer caster(GameTestHelper h,String metal){var p=player(h);PowerAttributes.set(p,"a:"+metal,1);PowerData.state(p,"a:"+metal,2);PowerData.reserve(p,metal,PowerConfig.RESERVE_CAP.get());PowerData.assignSlot(p,"a:"+metal,0);PowerService.control(p,new PowerNetwork.Control(2,"",1));return p;}
    private static final class Walker extends Pig{int calls;Walker(ServerLevel level){super(EntityType.PIG,level);setNoAi(true);setNoGravity(true);}@Override public void tick(){calls++;move(MoverType.SELF,getDeltaMovement());}}
    @GameTest(template="empty") public static void bubbleIsAnchoredCasterExemptAndCollapsesOnReleaseOrExit(GameTestHelper h){var p=caster(h,"bendalloy");try{h.assertTrue(BubbleService.create(p,"bendalloy"),"Held active power creates a bubble");var center=BubbleService.bubbles(h.getLevel()).getFirst().center();p.setPos(p.position().add(1,0,0));h.assertTrue(BubbleService.bubbles(h.getLevel()).getFirst().center().equals(center)&&BubbleService.rate(p)==1,"Moving the caster does not move the anchor or slow them");PowerService.control(p,new PowerNetwork.Control(2,"",0));h.assertTrue(BubbleService.bubbles(h.getLevel()).isEmpty(),"Releasing activation collapses the bubble");PowerService.control(p,new PowerNetwork.Control(2,"",1));BubbleService.create(p,"bendalloy");p.setPos(p.position().add(6,0,0));h.assertTrue(BubbleService.bubbles(h.getLevel()).isEmpty(),"Leaving the bubble collapses it");p.setPos(center.add(0,-p.getBbHeight()*.5,0));h.assertTrue(BubbleService.bubbles(h.getLevel()).isEmpty(),"Returning does not revive a collapsed bubble");}finally{BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void slowEntityLogicRetainsContinuousMovementAndNormalExitVelocity(GameTestHelper h){var p=caster(h,"bendalloy");var mob=new Walker(h.getLevel());try{BubbleService.create(p,"bendalloy");mob.setPos(p.position().add(1,0,0));mob.setDeltaMovement(.02,0,0);double x=mob.getX();int moving=0;for(int i=0;i<10;i++){double before=mob.getX();h.getLevel().tickNonPassenger(mob);if(mob.getX()>before)moving++;}h.assertTrue(mob.calls==5&&moving==10&&Math.abs(mob.getX()-x-.1)<1e-6,"Half-speed logic runs five times but movement advances all ten frames");h.assertTrue(Math.abs(mob.getDeltaMovement().x-.02)<1e-9,"Intrinsic momentum is not repeatedly multiplied");}finally{mob.discard();BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void acceleratedEntitiesAndFusesAdvanceRealLogicalTicks(GameTestHelper h){var p=caster(h,"cadmium");var mob=new Walker(h.getLevel());var tnt=new PrimedTnt(EntityType.TNT,h.getLevel());try{BubbleService.create(p,"cadmium");mob.setPos(p.position().add(1,0,0));mob.setDeltaMovement(.02,0,0);tnt.setPos(p.position().add(0,1,0));tnt.setNoGravity(true);tnt.setFuse(80);for(int i=0;i<10;i++){h.getLevel().tickNonPassenger(mob);h.getLevel().tickNonPassenger(tnt);}h.assertTrue(mob.calls==20&&Math.abs(mob.getX()-p.getX()-1-.4)<1e-6&&tnt.getFuse()==60,"Double-speed entities run twenty logical updates including TNT fuse countdown");}finally{mob.discard();tnt.discard();BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void skippedProjectileFramesStillCollideInsteadOfPassingThroughWalls(GameTestHelper h){var p=caster(h,"bendalloy");var snow=new Snowball(h.getLevel(),p);var wall=BlockPos.containing(p.position().add(2,1,0));try{BubbleService.create(p,"bendalloy");snow.setItem(new net.minecraft.world.item.ItemStack(Items.SNOWBALL));snow.setNoGravity(true);snow.setPos(p.position().add(1,1,0));snow.setDeltaMovement(2,0,0);h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());h.getLevel().tickNonPassenger(snow);h.assertTrue(snow.isRemoved(),"Fractional non-logic frame still raycasts and hits the wall");}finally{h.getLevel().setBlockAndUpdate(wall,Blocks.AIR.defaultBlockState());snow.discard();BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void blockEntityClocksAndPlayerActionsUseTheirTimeRates(GameTestHelper h){var p=caster(h,"cadmium");var other=player(h);var pos=BlockPos.containing(p.position().add(1,0,0));boolean pvp=BubbleConfig.PVP.get();try{BubbleService.create(p,"cadmium");h.getLevel().setBlockAndUpdate(pos,Blocks.FURNACE.defaultBlockState());var block=h.getLevel().getBlockEntity(pos);int[] ticks={0};for(int i=0;i<10;i++)BubbleService.blockTick(block,()->ticks[0]++);h.assertTrue(ticks[0]==20,"Ticking block entities accelerate with the bubble");BubbleConfig.PVP.set(false);other.setPos(p.position().add(1,0,1));for(int i=0;i<50;i++)BubbleService.updatePlayer(other);h.assertTrue(BubbleService.playerRate(other)==2&&Math.abs(other.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_SPEED)-8)<1e-6,"Other player attack speed follows time while caster remains exempt");int[] vitals={0};for(int i=0;i<10;i++)BubbleService.playerTimer(other,"testVitals",()->vitals[0]++);h.assertTrue(vitals[0]==20,"Player vital/item timer clock accelerates without duplicating network ticks");}finally{BubbleConfig.PVP.set(pvp);h.getLevel().setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());BubbleService.clearPlayer(other);BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void boundaryDeflectionsAreSmallAndPreserveMomentum(GameTestHelper h){var random=net.minecraft.util.RandomSource.create(4);var v=new Vec3(3,.4,1);for(int i=0;i<100;i++){var changed=BubbleService.deflect(v,random);h.assertTrue(Math.abs(changed.length()-v.length())<1e-7&&changed.normalize().dot(v.normalize())>=Math.cos(Math.toRadians(BubbleConfig.DEFLECTION_DEGREES.get()))-1e-8,"Random deviation stays inside configured angle and preserves speed");}var p=caster(h,"bendalloy");var mob=new Walker(h.getLevel());try{BubbleService.create(p,"bendalloy");var center=BubbleService.bubbles(h.getLevel()).getFirst().center();mob.setPos(center);mob.setDeltaMovement(v);BubbleService.crossed(mob,center.add(-6,0,0),center.add(6,0,0));h.assertTrue(!mob.getDeltaMovement().equals(v)&&Math.abs(mob.getDeltaMovement().length()-v.length())<1e-7,"Sweeping fully across a bubble applies boundary deviation");}finally{mob.discard();BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void disabledBubblesAndFuelDepletionPreserveAttributes(GameTestHelper h){var p=caster(h,"bendalloy");boolean enabled=BubbleConfig.ENABLED.get();try{BubbleService.create(p,"bendalloy");double fuel=PowerData.reserve(p,"bendalloy");BubbleConfig.ENABLED.set(false);BubbleService.tickPlayer(p);h.assertTrue(BubbleService.bubbles(h.getLevel()).isEmpty()&&PowerData.reserve(p,"bendalloy")==fuel&&PowerAttributes.strength(p,"a:bendalloy")==1,"Disabling collapses effects and preserves saved data");BubbleConfig.ENABLED.set(true);PowerData.reserve(p,"bendalloy",.001);BubbleService.tickPlayer(p);h.assertTrue(PowerData.state(p,"a:bendalloy")==0,"Fuel depletion stops burning");}finally{BubbleConfig.ENABLED.set(enabled);BubbleService.clearPlayer(p);}h.succeed();}
    @GameTest(template="empty") public static void bubblePacketRoundTripsAndRejectsUnboundedData(GameTestHelper h){var p=player(h);var packet=new BubblePacket(p.level().dimension().location().toString(),.5,List.of(new BubblePacket.Sphere(p.getUUID(),"bendalloy",p.position(),4,.5)));var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{BubblePacket.CODEC.encode(b,packet);h.assertTrue(BubblePacket.CODEC.decode(b).equals(packet),"Visual sphere and recipient time rate round trip");}finally{b.release();}boolean rejected=false;try{new BubblePacket("minecraft:overworld",Double.NaN,List.of());}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Invalid time rate rejected");h.succeed();}
    @GameTest(template="empty") public static void droppedItemPredictionUsesBubbleClockAndContinuousGravity(GameTestHelper h){
        for(String metal:List.of("bendalloy","cadmium")){
            var p=caster(h,metal);
            var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),p.getX()+1,p.getY(),p.getZ(),new net.minecraft.world.item.ItemStack(Items.IRON_NUGGET));
            var mob=new Walker(h.getLevel());
            try{
                BubbleService.create(p,metal);item.setDeltaMovement(0,-.01,0);
                h.assertTrue(BubbleService.predictsLocally(item)&&!BubbleService.predictsLocally(mob),"Dropped items use client bubble prediction without changing living-entity interpolation");
                int frames=metal.equals("bendalloy")?10:4,logicalTicks=metal.equals("bendalloy")?5:8;
                for(int i=0;i<frames;i++){double before=item.getY();h.getLevel().tickNonPassenger(item);h.assertTrue(item.getY()<before,"Airborne item advances downward on every bubble frame");}
                double velocity=-.01;for(int i=0;i<logicalTicks;i++)velocity=(velocity-.04)*.98;
                h.assertTrue(item.tickCount==logicalTicks&&Math.abs(item.getDeltaMovement().y-velocity)<1e-6,"Item age and intrinsic gravity advance on the same fractional clock used by client prediction");
            }finally{item.discard();mob.discard();BubbleService.clearPlayer(p);}
        }
        h.succeed();
    }
    private BubbleGameTests(){}
}
